// testAccCloudLoadBalancerPoolHealthMonitorDeleteOutOfBand deletes the monitor
// straight through the API, bypassing Terraform.
func testAccCloudLoadBalancerPoolHealthMonitorDeleteOutOfBand(name string) resource.TestCheckFunc {
	return func(s *terraform.State) error {
		rs, ok := s.RootModule().Resources[name]
		if !ok {
			return fmt.Errorf("resource %s not found in state", name)
		}
		client, err := acctest.NewGcoreClient()
		if err != nil {
			return err
		}
		projectID, err := attrOrDefault(rs.Primary.Attributes["project_id"], acctest.ProjectID())
		if err != nil {
			return fmt.Errorf("error parsing project_id: %w", err)
		}
		regionID, err := attrOrDefault(rs.Primary.Attributes["region_id"], acctest.RegionID())
		if err != nil {
			return fmt.Errorf("error parsing region_id: %w", err)
		}
		return client.Cloud.LoadBalancers.Pools.HealthMonitors.DeleteAndPoll(context.Background(), rs.Primary.Attributes["pool_id"],
			cloud.LoadBalancerPoolHealthMonitorDeleteParams{
				ProjectID: param.NewOpt(projectID),
				RegionID:  param.NewOpt(regionID),
			})
	}
}

// A destroyed health monitor is gone when its pool no longer reports one; a
// missing pool (torn down with the load balancer) counts as gone too.
func testAccCheckCloudLoadBalancerPoolHealthMonitorDestroy(s *terraform.State) error {
	client, err := acctest.NewGcoreClient()
	if err != nil {
		return err
	}

	for _, rs := range s.RootModule().Resources {
		if rs.Type != "gcore_cloud_load_balancer_pool_health_monitor" {
			continue
		}

		// A configuration that relies on the provider defaults leaves both
		// attributes null in state; the destroy check then uses the same defaults.
		projectID, err := attrOrDefault(rs.Primary.Attributes["project_id"], acctest.ProjectID())
		if err != nil {
			return fmt.Errorf("error parsing project_id: %w", err)
		}
		regionID, err := attrOrDefault(rs.Primary.Attributes["region_id"], acctest.RegionID())
		if err != nil {
			return fmt.Errorf("error parsing region_id: %w", err)
		}
		poolID := rs.Primary.Attributes["pool_id"]

		hm, err := client.Cloud.LoadBalancers.Pools.HealthMonitors.Get(context.Background(), poolID,
			cloud.LoadBalancerPoolHealthMonitorGetParams{
				ProjectID: param.NewOpt(projectID),
				RegionID:  param.NewOpt(regionID),
			})
		if err != nil {
			if acctest.IsNotFoundError(err) {
				continue
			}
			return fmt.Errorf("error getting health monitor of pool %s: %w", poolID, err)
		}
		if hm.ID == rs.Primary.ID {
			return fmt.Errorf("health monitor %s still exists on pool %s", rs.Primary.ID, poolID)
		}
	}
	return nil
}

