// attrOrDefault parses a state attribute as an id, using the fallback when the
// attribute is unset.
func attrOrDefault(attr, fallback string) (int64, error) {
	if attr == "" {
		attr = fallback
	}
	return strconv.ParseInt(attr, 10, 64)
}
